import { createImage } from './image.js';
import type { RgbaImage } from './image.js';
import type { AnimationFrame } from './gif.js';

/**
 * Built-in animation gallery for keyboard screens. Every animation is generated by this code (no
 * third-party artwork), so it is free to use and redistribute under OpenKey's licence. Generators are
 * deterministic (seeded), resolution-independent and loop seamlessly: every motion is periodic in the
 * loop phase `t` ∈ [0, 1), so frame N wraps exactly to frame 0.
 */
export interface GalleryAnimation {
  id: string;
  name: string;
  /** One line for the gallery card. */
  description: string;
  frames: number;
  delayMs: number;
  /** Paints the image at loop phase t ∈ [0, 1]; t = 0 and t = 1 give identical images. */
  paint(img: RgbaImage, t: number): void;
}

type Rgb = [number, number, number];
const TAU = Math.PI * 2;
const clamp = (x: number, a = 0, b = 1): number => (x < a ? a : x > b ? b : x);
const frac = (x: number): number => x - Math.floor(x);
const mix = (a: number, b: number, k: number): number => a + (b - a) * k;
const smooth = (e0: number, e1: number, x: number): number => {
  const k = clamp((x - e0) / (e1 - e0));
  return k * k * (3 - 2 * k);
};

function hsv(h: number, s: number, v: number): Rgb {
  const i = Math.floor(frac(h) * 6);
  const f = frac(h) * 6 - i;
  const p = v * (1 - s);
  const q = v * (1 - f * s);
  const u = v * (1 - (1 - f) * s);
  const c: Rgb[] = [
    [v, u, p],
    [q, v, p],
    [p, v, u],
    [p, q, v],
    [u, p, v],
    [v, p, q],
  ];
  return c[i % 6]!;
}

/** Small seeded PRNG (mulberry32) so every render is identical. */
function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Per-pixel shader helper: u, v ∈ [0, 1) with square aspect around the centre. */
function shade(img: RgbaImage, fn: (u: number, v: number) => Rgb): void {
  const { width: w, height: h, data } = img;
  const s = Math.min(w, h);
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      const [r, g, b] = fn((x + 0.5 - (w - s) / 2) / s, (y + 0.5 - (h - s) / 2) / s);
      const i = (y * w + x) * 4;
      data[i] = clamp(r) * 255;
      data[i + 1] = clamp(g) * 255;
      data[i + 2] = clamp(b) * 255;
      data[i + 3] = 255;
    }
}

/** Additive plot of a soft dot (used by particle animations). */
function dot(img: RgbaImage, cx: number, cy: number, radius: number, c: Rgb, alpha = 1): void {
  const { width: w, height: h, data } = img;
  const s = Math.min(w, h);
  const px = cx * s + (w - s) / 2;
  const py = cy * s + (h - s) / 2;
  const r = Math.max(0.6, radius * s);
  for (let y = Math.floor(py - r - 1); y <= Math.ceil(py + r + 1); y++)
    for (let x = Math.floor(px - r - 1); x <= Math.ceil(px + r + 1); x++) {
      if (x < 0 || y < 0 || x >= w || y >= h) continue;
      const k = alpha * (1 - smooth(r * 0.6, r + 0.8, Math.hypot(x + 0.5 - px, y + 0.5 - py)));
      if (k <= 0) continue;
      const i = (y * w + x) * 4;
      data[i] = Math.min(255, data[i]! + c[0] * 255 * k);
      data[i + 1] = Math.min(255, data[i + 1]! + c[1] * 255 * k);
      data[i + 2] = Math.min(255, data[i + 2]! + c[2] * 255 * k);
    }
}

function fill(img: RgbaImage, c: Rgb): void {
  for (let i = 0; i < img.data.length; i += 4) {
    img.data[i] = c[0] * 255;
    img.data[i + 1] = c[1] * 255;
    img.data[i + 2] = c[2] * 255;
    img.data[i + 3] = 255;
  }
}

/** Signed distance to a rounded box centred at the origin. */
function sdBox(x: number, y: number, bx: number, by: number, r: number): number {
  const qx = Math.abs(x) - bx + r;
  const qy = Math.abs(y) - by + r;
  return Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - r;
}

const STARS = (() => {
  const r = rng(7);
  return Array.from({ length: 110 }, () => ({ a: r() * TAU, z: r(), k: r() < 0.6 ? 1 : 2, hue: r() }));
})();

const RAIN = (() => {
  const r = rng(42);
  return Array.from({ length: 16 }, () => ({ off: r(), k: r() < 0.5 ? 1 : 2, len: 0.35 + r() * 0.4, glyphs: Array.from({ length: 24 }, () => Math.floor(r() * 0x7fff)) }));
})();

const EQ = (() => {
  const r = rng(3);
  return Array.from({ length: 10 }, () => ({ k: 1 + Math.floor(r() * 3), p: r(), a: 0.45 + r() * 0.4 }));
})();

export const GALLERY: readonly GalleryAnimation[] = [
  {
    id: 'openkey-pulse',
    name: 'OpenKey pulse',
    description: 'The OpenKey keyboard mark with a breathing glow.',
    frames: 24,
    delayMs: 60,
    paint(img, t) {
      const glow = 0.5 + 0.5 * Math.cos(TAU * t);
      shade(img, (u, v) => {
        const x = u - 0.5;
        const y = v - 0.5;
        const bg = 0.05 + 0.06 * (1 - Math.hypot(x, y) * 1.6);
        let r = bg * 0.5;
        let g = bg * 0.6;
        let b = bg * 1.4;
        // Case outline, three keys (the last one accent) and a space bar, as in the app icon.
        const outline = Math.abs(sdBox(x, y, 0.36, 0.22, 0.06)) - 0.02;
        const keys = Math.min(sdBox(x + 0.18, y + 0.06, 0.055, 0.04, 0.015), sdBox(x - 0.0, y + 0.06, 0.055, 0.04, 0.015));
        const accent = sdBox(x - 0.18, y + 0.06, 0.055, 0.04, 0.015);
        const space = sdBox(x, y - 0.09, 0.2, 0.035, 0.015);
        const white = Math.min(outline, keys, space);
        const halo = Math.exp(-Math.max(Math.min(white, accent), 0) * (18 - 8 * glow)) * (0.25 + 0.35 * glow);
        r += 0.48 * halo;
        g += 0.58 * halo;
        b += 1.0 * halo;
        if (white < 0) [r, g, b] = [0.92, 0.94, 1];
        if (accent < 0) [r, g, b] = [mix(0.35, 0.6, glow), mix(0.45, 0.7, glow), 1];
        return [r, g, b];
      });
    },
  },
  {
    id: 'aurora',
    name: 'Aurora',
    description: 'Northern-light curtains drifting over a starry sky.',
    frames: 30,
    delayMs: 60,
    paint(img, t) {
      shade(img, (u, v) => {
        const w = Math.sin(u * 7 + Math.sin(v * 3 + TAU * t) * 1.4 + TAU * t);
        const band = Math.exp(-Math.pow(v - 0.42 - 0.13 * w, 2) * 38) * (0.55 + 0.45 * Math.sin(u * 13 - TAU * t));
        const [r, g, b] = hsv(0.36 + 0.18 * u + 0.05 * Math.sin(TAU * t), 0.75, band);
        const star = frac(Math.sin(Math.floor(u * 64) * 12.9898 + Math.floor(v * 64) * 78.233) * 43758.55) > 0.993 ? 0.6 + 0.4 * Math.sin(TAU * t + u * 40) : 0;
        const sky = 0.03 + 0.07 * v;
        return [r + sky * 0.3 + star * (1 - band), g + sky * 0.4 + star * (1 - band), b + sky + star * (1 - band)];
      });
    },
  },
  {
    id: 'plasma',
    name: 'Plasma',
    description: 'Flowing rainbow plasma, a classic demoscene effect.',
    frames: 30,
    delayMs: 50,
    paint(img, t) {
      const p = TAU * t;
      shade(img, (u, v) => {
        const a =
          Math.sin(u * 9 + p) +
          Math.sin(v * 8 - p) +
          Math.sin((u + v) * 6 + 2 * p) +
          Math.sin(Math.hypot(u - 0.5 - 0.2 * Math.cos(p), v - 0.5 - 0.2 * Math.sin(p)) * 16);
        return hsv(frac(a / 8 + t), 0.85, 0.85 + 0.15 * Math.sin(a * 2));
      });
    },
  },
  {
    id: 'starfield',
    name: 'Warp',
    description: 'A starfield rushing towards you.',
    frames: 24,
    delayMs: 50,
    paint(img, t) {
      fill(img, [0.01, 0.01, 0.04]);
      for (const s of STARS) {
        const z = frac(s.z + s.k * t);
        const r = z * z * 0.75;
        const c = hsv(0.55 + s.hue * 0.15, 0.25, 0.35 + 0.65 * z);
        for (let k = 0; k < 3; k++) {
          const rr = r * (1 - k * 0.06);
          dot(img, 0.5 + Math.cos(s.a) * rr, 0.5 + Math.sin(s.a) * rr, 0.004 + z * 0.012, c, 1 - k * 0.35);
        }
      }
    },
  },
  {
    id: 'equalizer',
    name: 'Equalizer',
    description: 'Bouncing level meter bars in green, amber and red.',
    frames: 24,
    delayMs: 70,
    paint(img, t) {
      shade(img, (u, v) => {
        const i = Math.min(EQ.length - 1, Math.floor(u * EQ.length));
        const inBar = frac(u * EQ.length) > 0.16 && frac(u * EQ.length) < 0.84;
        const e = EQ[i]!;
        const level = 0.12 + e.a * Math.abs(Math.sin(TAU * (e.k * t + e.p) / 2) ** 2 + 0.25 * Math.sin(TAU * (2 * e.k * t + e.p)));
        const y = 1 - v;
        const segment = frac(v * 22) > 0.22;
        if (inBar && segment && y < level) {
          const [r, g, b] = y < 0.55 ? [0.15, 0.9, 0.4] : y < 0.8 ? [1, 0.8, 0.15] : [1, 0.25, 0.2];
          return [r, g, b];
        }
        const base = inBar && segment ? 0.07 : 0.025;
        return [base, base, base * 1.6];
      });
    },
  },
  {
    id: 'ripple',
    name: 'Ripple',
    description: 'Calm rings spreading from the centre.',
    frames: 30,
    delayMs: 60,
    paint(img, t) {
      shade(img, (u, v) => {
        const d = Math.hypot(u - 0.5, v - 0.5);
        const ring = Math.pow(0.5 + 0.5 * Math.cos(TAU * (d * 6 - t)), 6) * (1 - smooth(0.3, 0.72, d));
        const [r, g, b] = hsv(0.5 + d * 0.35, 0.7, ring);
        return [r + 0.02, g + 0.04, b + 0.08];
      });
    },
  },
  {
    id: 'keycap-wave',
    name: 'Keycap wave',
    description: 'A rainbow wave rolling across a grid of keycaps.',
    frames: 24,
    delayMs: 60,
    paint(img, t) {
      shade(img, (u, v) => {
        const n = 4;
        const cx = Math.floor(u * n);
        const cy = Math.floor(v * n);
        const lx = frac(u * n) - 0.5;
        const ly = frac(v * n) - 0.5;
        const d = sdBox(lx, ly, 0.4, 0.4, 0.12);
        if (d > 0) return [0.03, 0.035, 0.05];
        const phase = (cx + cy) / (2 * n);
        const lit = 0.5 + 0.5 * Math.cos(TAU * (t - phase));
        const [r, g, b] = hsv((cx + cy) / 8 + t, 0.7, 0.25 + 0.75 * lit);
        const bevel = d > -0.05 ? 0.75 : 1;
        return [r * bevel, g * bevel, b * bevel];
      });
    },
  },
  {
    id: 'rain',
    name: 'Glyph rain',
    description: 'Falling columns of tiny glyphs.',
    frames: 30,
    delayMs: 60,
    paint(img, t) {
      shade(img, (u, v) => {
        const col = Math.min(RAIN.length - 1, Math.floor(u * RAIN.length));
        const c = RAIN[col]!;
        const head = frac(c.off + c.k * t) * (1 + c.len);
        const behind = head - v;
        if (behind < 0 || behind > c.len) return [0, 0.02, 0.01];
        // 3×5 glyph in each 8-pixel cell, picked from the column's seeded table.
        const cellY = Math.floor(v * RAIN.length);
        const gx = Math.floor(frac(u * RAIN.length) * 4);
        const gy = Math.floor(frac(v * RAIN.length) * 6);
        const on = gx < 3 && gy < 5 && (c.glyphs[cellY % 24]! >> (gy * 3 + gx)) & 1;
        if (!on) return [0, 0.02, 0.01];
        const k = 1 - behind / c.len;
        return behind < 0.04 ? [0.75, 1, 0.8] : [0.05 * k, 0.95 * k, 0.35 * k];
      });
    },
  },
  {
    id: 'orbit',
    name: 'Orbit',
    description: 'Three planets circling a glowing sun.',
    frames: 36,
    delayMs: 60,
    paint(img, t) {
      shade(img, (u, v) => {
        const d = Math.hypot(u - 0.5, v - 0.5);
        const sun = Math.exp(-d * 14) * 1.2;
        const rings = [0.18, 0.29, 0.4].reduce((a, r) => a + Math.exp(-Math.pow((d - r) * 220, 2)) * 0.12, 0);
        return [sun + 0.02 + rings, sun * 0.75 + 0.02 + rings, sun * 0.2 + 0.06 + rings * 1.4];
      });
      const planets: [number, number, number, Rgb][] = [
        [0.18, 1, 0.035, [0.95, 0.45, 0.3]],
        [0.29, -2, 0.045, [0.3, 0.7, 1]],
        [0.4, 3, 0.03, [0.6, 1, 0.6]],
      ];
      for (const [r, k, size, c] of planets) dot(img, 0.5 + Math.cos(TAU * k * t) * r, 0.5 + Math.sin(TAU * k * t) * r, size, c);
    },
  },
  {
    id: 'heartbeat',
    name: 'Heartbeat',
    description: 'A heart beating twice per loop.',
    frames: 30,
    delayMs: 50,
    paint(img, t) {
      const beat = Math.exp(-Math.pow(frac(t * 2) - 0.15, 2) * 90);
      const s = 1 + 0.14 * beat;
      shade(img, (u, v) => {
        const x = (u - 0.5) / (0.3 * s);
        const y = (0.47 - v) / (0.3 * s) + 0.2;
        // Implicit heart curve: (x² + y² − 1)³ − x²y³ ≤ 0.
        const f = Math.pow(x * x + y * y - 1, 3) - x * x * y * y * y;
        const glow = Math.exp(-Math.max(f, 0) * 6) * (0.25 + 0.5 * beat);
        if (f <= 0) return [mix(0.85, 1, beat), mix(0.12, 0.3, beat), mix(0.25, 0.4, beat)];
        return [0.04 + glow * 0.9, 0.01 + glow * 0.15, 0.04 + glow * 0.3];
      });
    },
  },
];

export function galleryAnimation(id: string): GalleryAnimation | undefined {
  return GALLERY.find((a) => a.id === id);
}

/** Renders one gallery animation as frames ready for `prepareAnimation`. */
export function renderGallery(id: string, width = 128, height = 128, frames?: number): AnimationFrame[] {
  const a = galleryAnimation(id);
  if (!a) throw new Error(`Unknown gallery animation: ${id}`);
  const n = frames ?? a.frames;
  return Array.from({ length: n }, (_, i) => {
    const image = createImage(width, height);
    a.paint(image, i / n);
    return { image, delayMs: a.delayMs };
  });
}
